diagnostic_sources.blend:
extends LearnedBipedMotion

var ramp_seconds: float = 0.2
var settle_seconds: float = 0.0
var stop_phase: float = -1.0
var _was_moving: bool = false
var _have_stopped: bool = false
var _pause_seconds: float = 0.0
var _saved_step: int = 0
var _saved_frame: int = 0
var _ramp_elapsed: float = -1.0
var _restart_pose := PackedFloat64Array([0, 0, 0, 0])

func _physics_process(delta: float) -> void:
	if not _enabled or not is_instance_valid(_hardware) or not _hardware.is_built():
		return
	if _move_input.y < 0.05:
		if _was_moving:
			_saved_step = _control_step
			_saved_frame = _physics_frame
			_pause_seconds = 0.0
			_have_stopped = true
		_was_moving = false
		_ramp_elapsed = -1.0
		_pause_seconds += delta
	else:
		if not _was_moving and _have_stopped:
			var obs: PackedFloat64Array = observation()
			for index: int in ACTIONS:
				_restart_pose[index] = clampf(rad_to_deg(obs[index]) / float(policy.action_scale_deg), -1.0, 1.0)
			_ramp_elapsed = 0.0
			if settle_seconds > 0.0 and _pause_seconds < settle_seconds:
				_control_step = _saved_step
				_physics_frame = _saved_frame
		_was_moving = true
	super._physics_process(delta)
	if _ramp_elapsed >= 0.0:
		_ramp_elapsed += delta

func apply_action(action: PackedFloat64Array) -> void:
	var blended: PackedFloat64Array = action.duplicate()
	if _ramp_elapsed >= 0.0 and _ramp_elapsed < ramp_seconds:
		var strength: float = smoothstep(0.0, ramp_seconds, _ramp_elapsed)
		for index: int in ACTIONS:
			blended[index] = lerpf(_restart_pose[index], action[index], strength)
	super.apply_action(blended)
